local function escChar(c)
    if c == "\n" then
        return "\\n"
    elseif c == "\r" then
        return "\\r"
    elseif c == "\t" then
        return "\\t"
    elseif c == '"' then
        return '\\"'
    elseif c == "\\" then
        return "\\\\"
    end
    return string.format("\\%03d", string.byte(c))
end

-- String dikutip + di-escape, dipotong kalau kepanjangan.
local function q(s, max)
    s = tostring(s)
    max = max or 200
    local cut = false
    if #s > max then
        s = string.sub(s, 1, max)
        cut = true
    end
    s = string.gsub(s, '[%c"\\]', escChar)
    return '"' .. s .. '"' .. (cut and "..." or "")
end

local function num(n)
    if type(n) ~= "number" then
        return tostring(n)
    end
    if n == math.floor(n) and math.abs(n) < 1e15 then
        return string.format("%d", n)
    end
    local s = string.format("%.3f", n)
    s = string.gsub(s, "%.?0+$", "")
    return s
end

local function fnSig(fn)
    local d = debug
    if type(d) == "table" and type(d.info) == "function" then
        local ok, np, va = pcall(d.info, fn, "a")
        if ok and type(np) == "number" then
            local s = "function(" .. tostring(np) .. (va and ", vararg" or "") .. ")"
            local okN, nm = pcall(d.info, fn, "n")
            if okN and type(nm) == "string" and nm ~= "" then
                s = s .. " " .. nm
            end
            return s
        end
    end
    return "function"
end

local function v3s(v)
    local x, y, z = prop(v, "X"), prop(v, "Y"), prop(v, "Z")
    if type(x) == "number" and type(y) == "number" and type(z) == "number" then
        return string.format("(%.1f, %.1f, %.1f)", x, y, z)
    end
    return "(?)"
end

-- Nilai skalar -> string. Tabel -> nil (pemanggil yang urus).
local function fmtv(v)
    local t = typeof(v)
    if t == "nil" then
        return "nil"
    elseif t == "string" then
        return q(v)
    elseif t == "number" then
        return num(v)
    elseif t == "boolean" then
        return tostring(v)
    elseif t == "function" then
        return fnSig(v)
    elseif t == "table" then
        return nil
    elseif t == "Instance" then
        if prop(v, "ClassName") == "Player" then
            return "Player(" .. tostring(prop(v, "Name")) .. ")"
        end
        return fullName(v)
    elseif t == "Vector3" then
        return "Vector3" .. v3s(v)
    elseif t == "CFrame" then
        return "CFrame" .. v3s(prop(v, "Position"))
    elseif t == "Color3" then
        local r, g, b = prop(v, "R"), prop(v, "G"), prop(v, "B")
        if type(r) == "number" and type(g) == "number" and type(b) == "number" then
            return string.format("Color3(%d, %d, %d)", math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5))
        end
    end
    local ok, s = pcall(tostring, v)
    if t == "EnumItem" then
        return ok and tostring(s) or "EnumItem"
    end
    return t .. "(" .. (ok and tostring(s) or "?") .. ")"
end

local function keyStr(k)
    if type(k) == "string" and string.match(k, "^[%a_][%w_]*$") then
        return k
    end
    return "[" .. (fmtv(k) or "table") .. "]"
end

local function hasMeta(v)
    local ok, mt = pcall(getmetatable, v)
    return ok and mt ~= nil
end

-- Serialisasi ringkas satu baris (dipakai buat argumen remote).
local function ser(v, depth, seen)
    local s = fmtv(v)
    if s then
        return s
    end
    if type(v) ~= "table" then
        return typeof(v)
    end
    if depth <= 0 then
        return "{...}"
    end
    seen = seen or {}
    if seen[v] then
        return "{cycle}"
    end
    seen[v] = true
    local parts = {}
    local okIt = pcall(function()
        local n, idx = 0, 1
        for k, val in next, v do
            n = n + 1
            if n > 16 then
                parts[#parts + 1] = "..."
                break
            end
            if k == idx then
                parts[#parts + 1] = ser(val, depth - 1, seen)
                idx = idx + 1
            else
                parts[#parts + 1] = keyStr(k) .. "=" .. ser(val, depth - 1, seen)
            end
        end
    end)
    seen[v] = nil
    if not okIt then
        parts[#parts + 1] = "<iter error>"
    end
    return "{" .. table.concat(parts, ", ") .. "}" .. (hasMeta(v) and "<mt>" or "")
end

local function show(v)
    return fmtv(v) or ser(v, 2)
end

local function serArgs(args, maxLen)
    maxLen = maxLen or 300
    local parts = {}
    local n = (type(args) == "table" and (args.n or #args)) or 0
    for i = 1, n do
        parts[#parts + 1] = ser(args[i], 2)
    end
    local s = table.concat(parts, ", ")
    if #s > maxLen then
        s = string.sub(s, 1, maxLen) .. "..."
    end
    return s
end

local function stripRich(s)
    s = string.gsub(tostring(s or ""), "<[^>]->", "")
    return s
end

local function normId(id)
    if id == nil then
        return nil
    end
    return string.match(tostring(id), "%d+")
end

local function attrsInline(inst, cap)
    if typeof(inst) ~= "Instance" then
        return ""
    end
    local ok, a = pcall(inst.GetAttributes, inst)
    if not ok or type(a) ~= "table" then
        return ""
    end
    -- salinan attribute (mis. {Role="Doctor"}) jangan sampai muncul di probe getgc
    own(a)
    local names = {}
    for k in pairs(a) do
        names[#names + 1] = tostring(k)
    end
    if #names == 0 then
        return ""
    end
    table.sort(names)
    local parts = {}
    for i, k in ipairs(names) do
        if i > (cap or 40) then
            parts[#parts + 1] = "+" .. (#names - i + 1) .. " more"
            break
        end
        parts[#parts + 1] = k .. "=" .. show(a[k])
    end
    return table.concat(parts, ", ")
end

