-- Pemain pemilik instance (instance = Player, atau ada di dalam karakter).
local function playerOf(inst)
    if typeof(inst) ~= "Instance" then
        return nil
    end
    if prop(inst, "ClassName") == "Player" then
        return inst
    end
    local n, hops = inst, 0
    while n and hops < 8 do
        local ok, p = pcall(Players.GetPlayerFromCharacter, Players, n)
        if ok and p then
            return p
        end
        n = prop(n, "Parent")
        hops = hops + 1
    end
    return nil
end

local function ownerSuffix(inst)
    local p = playerOf(inst)
    if p then
        return " [" .. pname(p) .. "]"
    end
    return ""
end

local function posOf(inst)
    local p
    if isA(inst, "BasePart") then
        p = prop(inst, "Position")
    elseif isA(inst, "Model") then
        local ok, cf = pcall(inst.GetPivot, inst)
        p = ok and cf and prop(cf, "Position") or nil
    else
        local h = findChild(inst, "Handle")
        p = h and prop(h, "Position") or nil
    end
    if p then
        return v3s(p)
    end
    return "(?)"
end

