    end
    if ReplicatedFirst then
        list[#list + 1] = { "ReplicatedFirst", ReplicatedFirst }
    end
    local sps = childOfClass(StarterPlayer, "StarterPlayerScripts")
    if sps then
        list[#list + 1] = { "StarterPlayerScripts", sps }
    end
    return list
end

-- descCache: tabel opsional [root] = GetDescendants() supaya snapshot tidak scan berulang.
local function resolve(path, descCache)
    local segs = {}
    for s in string.gmatch(path, "[^.]+") do
        segs[#segs + 1] = s
    end
    if #segs == 0 then
        return nil
    end
    local roots = moduleRoots()
    for _, r in ipairs(roots) do
        local node = r[2]
        for _, s in ipairs(segs) do
            node = node and findChild(node, s)
        end
        if node then
            return node, r[1]
        end
    end
    local last = segs[#segs]
    for _, r in ipairs(roots) do
        local list = descCache and descCache[r[2]]
        if not list then
            list = descendants(r[2])
            if descCache then
                descCache[r[2]] = list
            end
        end
        for _, d in ipairs(list) do
            if d.Name == last then
                local ok, node = true, d
                for i = #segs - 1, 1, -1 do
                    node = prop(node, "Parent")
                    if not node or prop(node, "Name") ~= segs[i] then
                        ok = false
                        break
                    end
                end
                if ok then
                    return d, r[1]
                end
            end
        end
    end
    return nil
end

-- require di thread sendiri (identity opsional) dengan timeout, biar modul yang nge-yield tidak bikin macet.
-- Return ok, hasil, identity yang benar-benar dipakai (string, buat label).
-- Cuma config data murni (ReplicatedStorage.shared.configurations) yang aman di-require.
local function isConfigModule(inst)
    local shared = ReplicatedStorage and findChild(ReplicatedStorage, "shared")
    local cfg = shared and findChild(shared, "configurations")
    if not cfg then
        return false
    end
    local ok, inside = pcall(function()
        return inst:IsDescendantOf(cfg)
    end)
    return ok and inside or false
end

local function timedRequire(inst, ident, timeout)
    if type(require) ~= "function" then
        return false, "require missing", "?"
    end
    local req = require
    local getId, setId = idFns()
    local box = { done = false, used = "current" }
    timeout = timeout or 3
    task.spawn(function()
        local prevId = nil
        if ident and setId then
            if getId then
                local okG, v = pcall(getId)
                if okG then
                    prevId = v
                end
            end
            local okS = pcall(setId, ident)
            box.used = okS and tostring(ident) or "current (setthreadidentity failed)"
            if okS and getId then
                local okG2, v2 = pcall(getId)
                if okG2 and v2 ~= nil and v2 ~= ident then
                    box.used = tostring(v2) .. " (asked " .. tostring(ident) .. ")"
                end
            end
        elseif ident then
            box.used = "current (no setthreadidentity)"
        end
        local ok, res = pcall(req, inst)
        if prevId ~= nil then
            pcall(setId, prevId)
        end
        box.ok, box.res, box.done = ok, res, true
    end)
    local t0 = os.clock()
    while not box.done and os.clock() - t0 < timeout do
        task.wait(0.05)
    end
    if not box.done then
        return false, "timeout: module yielded > " .. tostring(timeout) .. "s", box.used
    end
    return box.ok, box.res, box.used
end

local function countKeys(t, cap)
    local n = 0
    pcall(function()
        for _ in next, t do
            n = n + 1
            if n >= (cap or 100000) then
                break
            end
        end
    end)
    return n
end

local function reqDesc(ok, res)
    if not ok then
        return "error: " .. string.sub(tostring(res), 1, 200)
    end
    if type(res) == "table" then
        return "ok (table, " .. countKeys(res) .. " keys" .. (hasMeta(res) and ", metatable" or "") .. ")"
    end
    return "ok (" .. typeof(res) .. ")"
end

local function pickTestModule(descCache)
    for _, p in ipairs({ "shared.configurations.gameConfig", "shared.configurations.teamsConfig", "shared.configurations.roles" }) do
        local m = resolve(p, descCache)
        if m and isA(m, "ModuleScript") then
            return m, p
        end
    end
    for _, c in ipairs(children(resolve("shared.configurations", descCache))) do
        if isA(c, "ModuleScript") then
            return c, "shared.configurations child"
        end
    end
    for _, d in ipairs(descendants(ReplicatedStorage)) do
        if d.ClassName == "ModuleScript" and string.find(string.lower(d.Name), "config", 1, true) then
            return d, "name contains config"
        end
    end
    return nil
end

----------------------------------------------------------------------
-- GUI text, map container, prompt
----------------------------------------------------------------------
local function selfShown(c, cls)
    if LAYER[cls] then
        return prop(c, "Enabled") ~= false
    end
    if GUIOBJ[cls] then
        return prop(c, "Visible") ~= false
    end
    return true
end

-- Semua TextLabel/TextButton/TextBox yang kelihatan (diri + semua parent visible / enabled).
local function collectTexts(root, cap, skip)
    local out = {}
    local function walk(node)
        for _, c in ipairs(children(node)) do
            if #out >= cap then
                return
            end
            if c ~= skip then
                local cls = c.ClassName
                if selfShown(c, cls) then
                    if TEXTCLS[cls] then
                        local t = prop(c, "Text")
                        if type(t) == "string" and t ~= "" then
                            local s = stripRich(t)
                            if string.find(s, "%S") then
                                out[#out + 1] = { c, s }
                            end
                        end
                    end
                    walk(c)
                end
            end
        end
    end
    walk(root)
    return out
end

local function mapWord(ln)
    for _, w in ipairs(MAP_WORDS) do
        if string.find(ln, w, 1, true) then
            return w
        end
    end
    return nil
end

local function isCharModel(c)
    local ok, p = pcall(Players.GetPlayerFromCharacter, Players, c)
    return ok and p ~= nil
end

-- Folder/Model di workspace (kedalaman <= maxDepth) yang namanya mirip Doors/Lockers/Map/...
local function findMapContainers(maxDepth, perWord)
    local found, perCount = {}, {}
    local queue = { { Workspace, 0 } }
    local qi = 1
    while qi <= #queue and #found < 30 and qi < 20000 do
        local node, d = queue[qi][1], queue[qi][2]
        qi = qi + 1
        for _, c in ipairs(children(node)) do
            local cls = c.ClassName
            if (cls == "Folder" or cls == "Model") and not isCharModel(c) then
                local w = mapWord(string.lower(c.Name))
                if w and (perCount[w] or 0) < perWord then
                    perCount[w] = (perCount[w] or 0) + 1
                    found[#found + 1] = { inst = c, word = w, depth = d + 1 }
                end
                if d + 1 < maxDepth and (not w or w == "map") then
                    queue[#queue + 1] = { c, d + 1 }
                end
            end
        end
    end
    return found
end

local function promptInfo(pp)
    return "ActionText=" .. q(tostring(prop(pp, "ActionText") or "")) .. " ObjectText=" .. q(tostring(prop(pp, "ObjectText") or ""))
        .. " hold=" .. num(prop(pp, "HoldDuration")) .. " dist=" .. num(prop(pp, "MaxActivationDistance"))
        .. " enabled=" .. tostring(prop(pp, "Enabled")) .. " in " .. fullName(prop(pp, "Parent"))
end

local function keyList(t, cap)
    local keys = {}
    pcall(function()
        for k in next, t do
            keys[#keys + 1] = (type(k) == "string" and k) or ("[" .. (fmtv(k) or "table") .. "]")
            if #keys >= (cap or 100) then
                break
            end
        end
    end)
    pcall(table.sort, keys)
    return table.concat(keys, ", ")
end

local function entryLess(a, b)
    if a.num and b.num then
        return a.k < b.k
    end
    if a.num ~= b.num then
        return a.num
    end
    return a.s < b.s
end

-- Dump tabel modul multi-baris. budget = { n, max, cut } dibagi ke seluruh modul.
local function dumpTable(out, t, pad, depth, budget, seen)
    local entries, total = {}, 0
    local okIt = pcall(function()
        for k, v in next, t do
            total = total + 1
            if #entries < 400 then
                entries[#entries + 1] = { k = k, v = v, s = keyStr(k), num = type(k) == "number" }
            end
            if total > 20000 then
                break
            end
        end
    end)
    pcall(table.sort, entries, entryLess)
    for _, e in ipairs(entries) do
        if budget.n >= budget.max then
            out(pad .. "... (entry cap " .. budget.max .. " reached)")
            budget.cut = true
            return
        end
        budget.n = budget.n + 1
        local v = e.v
        if type(v) == "table" then
            local mt = hasMeta(v) and " <metatable>" or ""
            if seen[v] then
                out(pad .. e.s .. " = {cycle}" .. mt)
            elseif depth <= 1 then
                out(pad .. e.s .. " = {" .. countKeys(v) .. " keys}" .. mt)
            else
                out(pad .. e.s .. " = {" .. mt)
                seen[v] = true
                dumpTable(out, v, pad .. "  ", depth - 1, budget, seen)
                seen[v] = nil
                out(pad .. "}")
                if budget.cut then
                    return
                end
            end
        else
            out(pad .. e.s .. " = " .. (fmtv(v) or typeof(v)))
        end
    end
    if total > #entries then
        out(pad .. "... (+" .. (total - #entries) .. " more keys)")
    end
    if not okIt then
        out(pad .. "<iteration error>")
    end
end

-- Cari sub-tabel bernama roles (case-insensitive) sampai kedalaman tertentu.
local function findRolesTables(t, path, depth, out, seen, found)
    if depth < 0 or seen[t] or found.n >= 10 then
        return
    end
    seen[t] = true
    pcall(function()
        for k, v in next, t do
            if type(v) == "table" then
                local p = path .. "." .. tostring(k)
                if type(k) == "string" and string.lower(k) == "roles" then
                    found.n = found.n + 1
                    out("  roles keys @" .. p .. ": " .. keyList(v, 100))
                end
                findRolesTables(v, p, depth - 1, out, seen, found)
            end
        end
    end)
end

-- Satu baris k=v (kedalaman 1) buat hasil getgc.
local function flatTable(t, cap)
    local parts, n = {}, 0
    pcall(function()
        for k, v in next, t do
            n = n + 1
            if n > cap then
                parts[#parts + 1] = "..."
                break
            end
            local vs = fmtv(v)
            if vs == nil then
                vs = "table(" .. countKeys(v, 1000) .. ")"
            end
            parts[#parts + 1] = keyStr(k) .. "=" .. vs
        end
    end)
    return "{" .. table.concat(parts, ", ") .. "}"
end

local function classSummary(list, from)
    local counts, order = {}, {}
    for i = from, #list do
        local cls = list[i].ClassName
        if not counts[cls] then
            counts[cls] = 0
            order[#order + 1] = cls
        end
        counts[cls] = counts[cls] + 1
    end
    table.sort(order, function(a, b)
        if counts[a] ~= counts[b] then
            return counts[a] > counts[b]
        end
        return a < b
    end)
    local parts = {}
    for i, cls in ipairs(order) do
        if i > 8 then
            parts[#parts + 1] = "..."
            break
        end
        parts[#parts + 1] = cls .. " x" .. counts[cls]
    end
    return table.concat(parts, ", ")
end

local function nodeLabel(c)
    local s = c.Name .. " [" .. c.ClassName .. "]"
    if isA(c, "ValueBase") then
        s = s .. " = " .. show(prop(c, "Value"))
    end
    local a = attrsInline(c, 8)
    if a ~= "" then
        s = s .. " {" .. a .. "}"
    end
    return s
end

local function treeWalk(out, node, depth, budget, kids)
    kids = kids or children(node)
    local n = #kids
    local shown = n
    if n > 40 then
        shown = 15
    end
    local pad = string.rep("  ", depth)
    for i = 1, shown do
        if budget.n >= TREE_CAP then
            budget.cut = true
            return
        end
        local c = kids[i]
        local sub = children(c)
        local line = pad .. nodeLabel(c)
        if depth >= TREE_DEPTH and #sub > 0 then
            line = line .. " (+" .. #sub .. " children, depth cap)"
        end
        out(line)
        budget.n = budget.n + 1
        if depth < TREE_DEPTH and #sub > 0 then
            treeWalk(out, c, depth + 1, budget, sub)
            if budget.cut then
                return
            end
        end
    end
    if n > shown then
        if budget.n >= TREE_CAP then
            budget.cut = true
            return
        end
        out(pad .. "... (+" .. (n - shown) .. " more, classes: " .. classSummary(kids, shown + 1) .. ")")
        budget.n = budget.n + 1
    end
end

-- Ada di dalam script Animate (karakter / StarterCharacterScripts)?
local function inAnimate(d)
    local n, hops = prop(d, "Parent"), 0
    while n and hops < 6 do
        if prop(n, "Name") == "Animate" then
            return true
        end
        n = prop(n, "Parent")
        hops = hops + 1
    end
    return false
end

-- Map id animasi -> nama (dipakai log ANIM). Id di luar Animate = animasi game (gameAnims).
local function addAnim(d)
    local id = normId(prop(d, "AnimationId"))
    if not id then
        return
    end
    local mine = inAnimate(d)
    if not mine then
        St.gameAnims[id] = true
    end
    if St.animNames[id] == nil then
        local nm = d.Name
        if nm == "Animation" or nm == "Anim" then
            nm = tostring(prop(prop(d, "Parent"), "Name")) .. "/" .. nm
        end
        St.animNames[id] = nm
    end
end

local function addAnimsIn(root)
    for _, d in ipairs(descendants(root)) do
        if d.ClassName == "Animation" then
            addAnim(d)
        end
    end
end

-- Tempat animasi tool (Knife/Glock biasanya simpan Animation di dalam Tool).
local function toolAnimRoots()
    local roots = {}
    local function add(x)
        if x then
            roots[#roots + 1] = x
        end
    end
    add(StarterPack)
    add(Lighting)
    for _, p in ipairs(Players:GetPlayers()) do
        add(childOfClass(p, "Backpack"))
    end
    return roots
end

-- Id animasi bawaan (script Animate) -> ditandai [default] di log.
-- Dibangun ulang tiap scan; id yang juga dipakai animasi game (mis. crawl yang ditaruh di slot walk
-- waktu downed) tidak dianggap default.
local function scanDefaultAnims()
    St.defaultAnims = own({})
    local holders = {}
    for _, pl in ipairs(Players:GetPlayers()) do
        local ch = prop(pl, "Character")
        local an = ch and findChild(ch, "Animate")
        if an then
            holders[#holders + 1] = an
        end
    end
    local scs = childOfClass(StarterPlayer, "StarterCharacterScripts")
    local an = scs and findChild(scs, "Animate")
    if an then
        holders[#holders + 1] = an
    end
    for _, h in ipairs(holders) do
        for _, d in ipairs(descendants(h)) do
            -- cuma slot standar Animate (walk/idle/...); slot custom (mis. crawl) tetap dianggap penting
            if d.ClassName == "Animation" and STD_ANIM_SLOTS[string.lower(tostring(prop(prop(d, "Parent"), "Name")))] then
                local id = normId(prop(d, "AnimationId"))
                if id and not St.gameAnims[id] then
                    St.defaultAnims[id] = true
                end
            end
        end
    end
end

local function connDesc(c)
    local fn = prop(c, "Function")
    local s = ""
    if type(fn) == "function" then
        local d = debug
        if type(d) == "table" and type(d.info) == "function" then
            local ok, src, line, nm = pcall(d.info, fn, "sln")
            if ok then
                s = tostring(src) .. ":" .. tostring(line) .. ((type(nm) == "string" and nm ~= "") and (" " .. nm) or "")
            end
        end
        if s == "" then
            s = fnSig(fn)
        end
    else
        s = "(no Lua function)"
    end
    if prop(c, "ForeignState") == true then
        s = s .. " [foreign]"
    end
    if prop(c, "Enabled") == false then
        s = s .. " [disabled]"
    end
    return s
end

----------------------------------------------------------------------
-- Lighting / EMP: helper baca saja (tidak pernah menulis property)
----------------------------------------------------------------------
-- "k=v k=v" untuk property yang ada; property yang error / nil / ternyata anak bernama sama dilewati.
local function propsInline(inst, list)
    local parts = {}
    for _, k in ipairs(list) do
        local ok, v = pcall(getp, inst, k)
        if ok and v ~= nil and typeof(v) ~= "Instance" then
            parts[#parts + 1] = k .. "=" .. show(v)
        end
    end
    return table.concat(parts, " ")
end

-- Property yang dipantau untuk anak Lighting / CurrentCamera (nil = class tidak menarik).
local function fxPropList(c)
    local cls = prop(c, "ClassName")
    if FX_PROPS[cls] then
        return FX_PROPS[cls]
    end
    if LIGHT_CLS[cls] then
        return LIGHT_INST_PROPS
    end
    if isA(c, "PostEffect") then
        return { "Enabled" }
    end
    if isA(c, "ValueBase") then
        return { "Value" }
    end
    return nil
end

-- Property yang dipantau di dalam ScreenGui Emp* (per class, biar tidak connect ke property yang tidak ada).
local function guiPropList(d)
    local cls = prop(d, "ClassName")
    if LAYER[cls] then
        return { "Enabled" }
    end
    if cls == "UIGradient" then
        return { "Enabled", "Offset", "Transparency" }
    end
    if not GUIOBJ[cls] then
        return nil
    end
    local list = { "Visible", "BackgroundTransparency", "BackgroundColor3" }
    if IMAGE_CLS[cls] then
        list[#list + 1] = "ImageTransparency"
        list[#list + 1] = "ImageColor3"
    elseif TEXTCLS[cls] then
        list[#list + 1] = "TextTransparency"
    elseif cls == "CanvasGroup" then
        list[#list + 1] = "GroupTransparency"
        list[#list + 1] = "GroupColor3"
    end
    return list
end

local function fxLine(c)
    local s = tostring(prop(c, "Name")) .. " [" .. tostring(prop(c, "ClassName")) .. "]"
    local list = fxPropList(c)
    local p = list and propsInline(c, list) or ""
    if p ~= "" then
        s = s .. " " .. p
    end
    local a = attrsInline(c, 10)
    if a ~= "" then
        s = s .. " {" .. a .. "}"
    end
    return s
end

-- ScreenGui yang namanya diawali "Emp" (huruf besar/kecil bebas): EmpInk, EmpAfterimage, ...
local function isEmpGui(g)
    if not isA(g, "ScreenGui") then
        return false
    end
    return string.find(string.lower(tostring(prop(g, "Name"))), "^emp") ~= nil
end

local function empGuiLine(g)
    return tostring(prop(g, "Name")) .. " [" .. tostring(prop(g, "ClassName")) .. "] Enabled=" .. tostring(prop(g, "Enabled"))
        .. " DisplayOrder=" .. tostring(prop(g, "DisplayOrder")) .. " IgnoreGuiInset=" .. tostring(prop(g, "IgnoreGuiInset"))
        .. " ResetOnSpawn=" .. tostring(prop(g, "ResetOnSpawn")) .. " descendants=" .. #descendants(g)
end

local function empTree(out, node, depth, budget)
    for _, c in ipairs(children(node)) do
        if budget.n >= EMP_TREE_CAP then
            budget.cut = true
            return
        end
        budget.n = budget.n + 1
        local p = propsInline(c, EMP_TREE_PROPS)
        out(string.rep("  ", depth + 1) .. tostring(prop(c, "Name")) .. " [" .. tostring(prop(c, "ClassName")) .. "]" .. (p ~= "" and (" " .. p) or ""))
        if depth < EMP_TREE_DEPTH then
            empTree(out, c, depth + 1, budget)
            if budget.cut then
                return
            end
        end
    end
end

local function lightLabel(inst)
    if inst == Lighting then
        return "Lighting"
    end
    return fullName(inst) .. " [" .. tostring(prop(inst, "ClassName")) .. "]"
end

----------------------------------------------------------------------
-- Live log: ring buffer + rate limit
----------------------------------------------------------------------
local function push(line)
    St.pushed = St.pushed + 1
    St.head = St.head % St.cap + 1
    St.buf[St.head] = line
    if St.count < St.cap then
        St.count = St.count + 1
    else
        St.dropped = St.dropped + 1
    end
end

local function stamp()
    local t = now()
    return string.format("[+%.2fs]", t - (St.liveT0 or t))
end

local function logLines()
    local out = {}
    local cap = St.cap
    local start = 1
    if St.count >= cap then
        start = St.head % cap + 1
    end
    for i = 0, St.count - 1 do
        out[#out + 1] = St.buf[(start - 1 + i) % cap + 1]
    end
    return out
end

-- maxN opsional: kuota per sumber per window (default RATE_MAX).
local function emit(cat, source, text, maxN)
    if not St.live then
        return
    end
    local t = now()
    local r = St.rate[source]
    if r == nil or t - r.start >= RATE_WINDOW then
        if r and r.sup > 0 then
            push(stamp() .. " " .. r.cat .. " suppressed " .. r.sup .. " lines from " .. source)
        end
        r = { start = t, n = 0, sup = 0, cat = cat }
        St.rate[source] = r
    end
    r.n = r.n + 1
    if r.n > (maxN or RATE_MAX) then
        r.sup = r.sup + 1
        return
    end
    text = tostring(text)
    if #text > 700 then
        text = string.sub(text, 1, 700) .. "..."
    end
    St.last = stamp() .. " " .. cat .. " " .. text
    push(St.last)
end

-- Tulis baris "suppressed N" untuk window yang sudah lewat (atau semua kalau force).
local function flushRate(force)
    local t = now()
    for src, r in pairs(St.rate) do
        if r.sup > 0 and (force or t - r.start >= RATE_WINDOW) then
            push(stamp() .. " " .. r.cat .. " suppressed " .. r.sup .. " lines from " .. src)
            r.sup = 0
        end
        if t - r.start >= RATE_WINDOW * 3 then
            St.rate[src] = nil
        end
    end
end

local function noteErr(where, err)
    local msg = tostring(where) .. ": " .. tostring(err)
    if #St.errs < 40 then
        St.errs[#St.errs + 1] = msg
    end
    if St.live then
        emit("ERR", "ERR:" .. string.sub(msg, 1, 60), msg)
    end
end

local function on(list, sig, fn, where)
    if sig == nil then
        return nil
    end
    local handler = function(...)
        local ok, err = pcall(fn, ...)
        if not ok then
            noteErr(where or "handler", err)
        end
    end
    local ok, c = pcall(function()
        return sig:Connect(handler)
    end)
    if ok and c then
        list[#list + 1] = c
        return c
    end
    return nil
end

local function once(inst, kind)
    if inst == nil then
        return false
    end
    local h = St.hk[inst]
    if not h then
        h = {}
        St.hk[inst] = h
    end
    if h[kind] then
        return false
    end
    h[kind] = true
    return true
end

----------------------------------------------------------------------
-- Live hooks
----------------------------------------------------------------------
local L = own({})

-- initial = true: instance baru muncul setelah live jalan (CharacterAdded, PlayerAdded, ChildAdded).
-- Attribute yang ikut ter-replikasi bareng instance tidak memicu AttributeChanged, jadi ditulis sekali.
function L.attr(inst, label, cat, initial)
    if typeof(inst) ~= "Instance" or not once(inst, "attr") then
        return
    end
    cat = cat or "ATTR"
    local last = own({})
    local okA, a = pcall(inst.GetAttributes, inst)
    if okA and type(a) == "table" then
        own(a)
        for k, v in pairs(a) do
            last[k] = v
        end
    end
    if initial then
        local s = attrsInline(inst, 40)
        if s ~= "" then
            emit(cat, cat .. "INIT:" .. label, label .. " initial: " .. s)
        end
    end
    on(St.liveConns, prop(inst, "AttributeChanged"), function(name)
        local okV, v = pcall(inst.GetAttribute, inst, name)
        if not okV then
            v = nil
        end
        local old = last[name]
        last[name] = v
        emit(cat, cat .. ":" .. label .. ":" .. tostring(name), label .. " " .. tostring(name) .. " = " .. show(v) .. "  (was " .. show(old) .. ")")
    end, "attr " .. label)
end

function L.value(v, label, initial)
    if not once(v, "val") then
        return
    end
    if initial then
        emit("VALUE", "VAL:" .. label, label .. " = " .. show(prop(v, "Value")) .. " (initial)")
    end
    on(St.liveConns, propSig(v, "Value"), function()
        emit("VALUE", "VAL:" .. label, label .. " = " .. show(prop(v, "Value")))
    end, "value " .. label)
end

function L.values(container, label, depth, initial)
    for _, c in ipairs(children(container)) do
        if isA(c, "ValueBase") then
            L.value(c, label .. "." .. c.Name, initial)
        elseif depth > 1 and (c.ClassName == "Folder" or c.ClassName == "Configuration") then
            L.values(c, label .. "." .. c.Name, depth - 1, initial)
        end
    end
end

function L.rsValues()
    local n = 0
    local function walk(node, depth)
        for _, c in ipairs(children(node)) do
            if n >= 200 then
                return
            end
            if isA(c, "ValueBase") then
                n = n + 1
                L.value(c, fullName(c))
            elseif depth < 3 then
                walk(c, depth + 1)
            end
        end
    end
    walk(ReplicatedStorage, 1)
end

function L.anim(p, animator)
    if not once(animator, "anim") then
        return
    end
    local name = pname(p)
    on(St.liveConns, prop(animator, "AnimationPlayed"), function(track)
        local a = prop(track, "Animation")
        local aname = (a and prop(a, "Name")) or prop(track, "Name") or "?"
        local id = normId(a and prop(a, "AnimationId") or nil)
        local key = name .. ":" .. tostring(id or aname)
        local t = now()
        local isDef = id and St.defaultAnims[id] or false
        local looped = prop(track, "Looped")
        local prio = enumName(prop(track, "Priority"))
        -- duplikat < 1 dtk dibuang; animasi gerak (default Animate, atau set custom yang looped dengan
        -- prioritas Core/Idle/Movement) cukup sekali per MOVE_DEDUPE dtk per pemain+id
        local moveCls = isDef or (looped == true and MOVE_PRIO[prio] == true)
        local seen = St.animSeen[key]
        if seen and t - seen < (moveCls and MOVE_DEDUPE or 1) then
            return
        end
        St.animSeen[key] = t
        local resolved = id and St.animNames[id] or nil
        local text = name .. " " .. q(tostring(aname)) .. " id=" .. tostring(id) .. " -> " .. tostring(resolved or "?")
            .. " looped=" .. tostring(looped) .. " prio=" .. prio
        if isDef then
            text = text .. " [default]"
        end
        emit("ANIM", isDef and ("ANIMDEF:" .. name) or ("ANIM:" .. key), text)
    end, "anim")
end

function L.hum(p, hum, initial)
    if not once(hum, "hum") then
        return
    end
    local name = pname(p)
    L.attr(hum, name .. ".Humanoid", nil, initial)
    local animator = childOfClass(hum, "Animator")
    if animator then
        L.anim(p, animator)
    end
    on(St.liveConns, prop(hum, "ChildAdded"), function(c)
        if c.ClassName == "Animator" then
            L.anim(p, c)
        end
    end, "hum child")
    on(St.liveConns, prop(hum, "StateChanged"), function(old, new)
        local nn = enumName(new)
        if BORING_STATES[nn] then
            return
        end
        emit("HUM", "STATE:" .. name, name .. " state " .. enumName(old) .. " -> " .. nn)
    end, "state")
    on(St.liveConns, propSig(hum, "WalkSpeed"), function()
        emit("HUM", "WS:" .. name, name .. " WalkSpeed = " .. num(prop(hum, "WalkSpeed")))
    end, "walkspeed")
    -- regen bawaan nembak tiap detik: cuma log lompatan >= 10, mati, atau balik penuh
    local lastHp = tonumber(prop(hum, "Health"))
    on(St.liveConns, prop(hum, "HealthChanged"), function(hp)
        hp = tonumber(hp)
        if not hp then
            return
        end
        local maxHp = tonumber(prop(hum, "MaxHealth"))
        local big = (lastHp == nil) or math.abs(hp - lastHp) >= 10 or (hp <= 0 and lastHp > 0) or (maxHp ~= nil and hp >= maxHp and lastHp < maxHp)
        if not big then
            return
        end
        emit("HUM", "HP:" .. name, name .. " Health = " .. num(hp) .. " (was " .. num(lastHp) .. ")")
        lastHp = hp
    end, "health")
    if p == LocalPlayer then
        on(St.liveConns, prop(hum, "Seated"), function(active, seat)
            emit("SEAT", "SEAT", "seated=" .. tostring(active) .. " seat=" .. (seat and fullName(seat) or "nil"))
        end, "seated")
    end
end

function L.char(p, ch, initial)
    if typeof(ch) ~= "Instance" or not once(ch, "char") then
        return
    end
    local name = pname(p)
    L.attr(ch, name .. ".Character", nil, initial)
    local function part(c, init)
        if c.ClassName == "Humanoid" then
            L.hum(p, c, init)
        elseif c.Name == "HumanoidRootPart" then
            L.attr(c, name .. ".HRP", nil, init)
        elseif isA(c, "ValueBase") then
            L.value(c, name .. ".Character." .. c.Name, init)
        end
    end
    for _, c in ipairs(children(ch)) do
        part(c, initial)
    end
    on(St.liveConns, prop(ch, "ChildAdded"), function(c)
        part(c, true)
        if isA(c, "Tool") then
            -- tool baru dipegang: Animation di dalamnya ikut dipetakan (stab/shoot)
            addAnimsIn(c)
            local a = attrsInline(c, 10)
            emit("TOOL", "TOOL:" .. name, name .. " equipped " .. q(c.Name) .. (a ~= "" and (" {" .. a .. "}") or ""))
        end
    end, "char child+")
    on(St.liveConns, prop(ch, "ChildRemoved"), function(c)
        if isA(c, "Tool") then
            emit("TOOL", "TOOL:" .. name, name .. " unequipped " .. q(c.Name))
        end
    end, "char child-")
end

-- Backpack: Animation di dalam tool yang baru dikasih ikut dipetakan id -> nama.
function L.backpack(bp)
    if typeof(bp) ~= "Instance" or not once(bp, "bp") then
        return
    end
    addAnimsIn(bp)
    on(St.liveConns, prop(bp, "DescendantAdded"), function(d)
        if d.ClassName == "Animation" then
            addAnim(d)
        end
    end, "backpack")
end

function L.player(p, initial)
    if not once(p, "player") then
        return
    end
    local name = pname(p)
    L.attr(p, name, nil, initial)
    L.values(p, name, 2, initial)
    L.backpack(childOfClass(p, "Backpack"))
    on(St.liveConns, propSig(p, "Team"), function()
        emit("PLAYER", "TEAM:" .. name, name .. " team -> " .. teamName(p))
    end, "team")
    on(St.liveConns, prop(p, "ChildAdded"), function(c)
        if c.ClassName == "Backpack" then
            L.backpack(c)
        end
        if SKIP_PLAYER_CHILD[c.ClassName] then
            return
        end
        local extra = ""
        if isA(c, "ValueBase") then
            extra = " = " .. show(prop(c, "Value"))
            L.value(c, name .. "." .. c.Name)
        elseif c.ClassName == "Folder" or c.ClassName == "Configuration" then
            L.values(c, name .. "." .. c.Name, 1, true)
        end
        emit("PLAYER", "PCHILD:" .. name, name .. " child added " .. c.Name .. " [" .. c.ClassName .. "]" .. extra)
    end, "player child")
    on(St.liveConns, prop(p, "CharacterAdded"), function(ch)
        emit("PLAYER", "CHAR:" .. name, name .. " spawned (CharacterAdded)")
        L.char(p, ch, true)
        -- Backpack dibuat ulang tiap spawn
        L.backpack(childOfClass(p, "Backpack"))
    end, "characteradded")
    local ch = prop(p, "Character")
    if ch then
        L.char(p, ch, initial)
    end
end

function L.players()
    for _, p in ipairs(Players:GetPlayers()) do
        L.player(p)
    end
    on(St.liveConns, prop(Players, "PlayerAdded"), function(p)
        emit("PLAYER", "JOIN", pname(p) .. " joined (team " .. teamName(p) .. ")")
        L.player(p, true)
    end, "playeradded")
    on(St.liveConns, prop(Players, "PlayerRemoving"), function(p)
        emit("PLAYER", "LEAVE", pname(p) .. " left")
    end, "playerremoving")
end

function L.globals()
    L.attr(Workspace, "Workspace")
    L.attr(ReplicatedStorage, "ReplicatedStorage")
    L.attr(Lighting, "Lighting")
    L.attr(Players, "Players")
    L.rsValues()
end

function L.scanAnims()
    local base = { ReplicatedStorage, ReplicatedFirst, StarterPlayer, childOfClass(LocalPlayer, "PlayerScripts") }
    for i = 1, 4 do
        addAnimsIn(base[i])
    end
    for _, r in ipairs(toolAnimRoots()) do
        addAnimsIn(r)
    end
    for _, p in ipairs(Players:GetPlayers()) do
        addAnimsIn(prop(p, "Character"))
    end
    scanDefaultAnims()
end

-- Return true kalau tag ini baru di-hook.
function L.hookTag(tag)
    if St.tagHooked[tag] or St.tagN >= 600 or not CollectionService then
        return false
    end
    St.tagHooked[tag] = true
    St.tagN = St.tagN + 1
    local cs = CollectionService
    local okA, sa = pcall(cs.GetInstanceAddedSignal, cs, tag)
    on(St.liveConns, okA and sa or nil, function(inst)
        emit("TAG", "TAG:" .. tag, "+" .. tag .. " " .. fullName(inst) .. ownerSuffix(inst))
    end, "tag+ " .. tag)
    local okR, sr = pcall(cs.GetInstanceRemovedSignal, cs, tag)
    on(St.liveConns, okR and sr or nil, function(inst)
        emit("TAG", "TAG:" .. tag, "-" .. tag .. " " .. fullName(inst) .. ownerSuffix(inst))
    end, "tag- " .. tag)
    return true
end

-- rescan = true (timer 10 dtk): tag yang baru ketemu sudah nempel di instance sebelum di-hook,
-- jadi pemegangnya ditulis sekarang (biasanya itu satu-satunya kejadian di ronde ini).
function L.tags(rescan)
    if not CollectionService then
        return
    end
    local ok, tags = pcall(CollectionService.GetAllTags, CollectionService)
    if not ok or type(tags) ~= "table" then
        return
    end
    for _, tag in ipairs(tags) do
        if type(tag) == "string" and L.hookTag(tag) and rescan then
            local okG, list = pcall(CollectionService.GetTagged, CollectionService, tag)
            if okG and type(list) == "table" then
                for i, inst in ipairs(list) do
                    if i > 15 then
                        emit("TAG", "TAG:" .. tag, "+" .. tag .. " ... +" .. (#list - 15) .. " more already tagged")
                        break
                    end
                    emit("TAG", "TAG:" .. tag, "+" .. tag .. " " .. fullName(inst) .. ownerSuffix(inst) .. " (already tagged when discovered)")
                end
            end
        end
    end
end

function L.chat()
    if not TextChatService then
        return
    end
    on(St.liveConns, prop(TextChatService, "MessageReceived"), function(msg)
        local src = prop(msg, "TextSource")
        local who = "SYSTEM"
        if src then
            local uid = prop(src, "UserId")
            local okP, pl = pcall(Players.GetPlayerByUserId, Players, uid)
            who = (okP and pl and pname(pl)) or tostring(prop(src, "Name"))
        end
        local ch = prop(msg, "TextChannel")
        local raw = tostring(prop(msg, "Text") or "")
        local text = stripRich(raw)
        local prefix = tostring(prop(msg, "PrefixText") or "")
        local meta = prop(msg, "Metadata")
        local line = who .. " [" .. tostring(ch and prop(ch, "Name") or "?") .. "] prefix=" .. q(prefix, 160) .. " text=" .. q(text, 400)
        if raw ~= text then
            line = line .. " raw=" .. q(raw, 400)
        end
        if type(meta) == "string" and meta ~= "" then
            line = line .. " meta=" .. q(meta, 120)
        end
        -- pesan sistem pakai kuota besar: burst pengumuman / vote di akhir malam jangan sampai ke-suppress
        emit("CHAT", "CHAT:" .. who, line, src == nil and RATE_MAX_SYSTEM_CHAT or nil)
    end, "chat")
end

-- Koneksi pertama ke OnClientEvent menguras antrean event Roblox (event yang datang sebelum ada
-- listener). Kalau inspector connect duluan, listener game yang connect belakangan kehilangan event itu.
-- Jadi: connect hanya kalau game sudah listen (getconnections), atau REMOTE_GRACE dtk setelah remote
-- baru muncul kalau getconnections tidak ada / tidak bisa dipercaya.
-- Return true/false = game punya listener atau tidak; nil = tidak bisa dicek.
local function gameListens(r)
    if not St.connsOk or type(getconnections) ~= "function" then
        return nil
    end
    local sig = prop(r, "OnClientEvent")
    if sig == nil then
        return nil
    end
    local ok, list = pcall(getconnections, sig)
    if ok and type(list) == "table" then
        return #list > 0
    end
    return nil
end

local function hookRemote(r)
    if St.remoteN >= 1500 or not once(r, "rin") then
        return
    end
    St.remoteN = St.remoteN + 1
    local name = fullName(r)
    on(St.liveConns, prop(r, "OnClientEvent"), function(...)
        emit("REMOTE_IN", "RIN:" .. name, name .. " (" .. serArgs(table.pack(...)) .. ")")
    end, "remote in")
end

-- isNew = muncul lewat DescendantAdded setelah live jalan.
function L.remote(r, isNew)
    if typeof(r) ~= "Instance" or not EVENT_CLS[r.ClassName] then
        return
    end
    local h = St.hk[r]
    if h and h.rin then
        return
    end
    local listens = gameListens(r)
    if listens == true or (listens == nil and not isNew) then
        St.remoteWait[r] = nil
        hookRemote(r)
    elseif St.remoteWait[r] == nil then
        St.remoteWait[r] = now()
    end
end

-- Dipanggil timer: hook remote yang ditunda begitu game sudah listen / masa tunggu habis.
function L.remoteTick()
    local t = now()
    local ready = {}
    for r, t0 in pairs(St.remoteWait) do
        if prop(r, "Parent") == nil then
            St.remoteWait[r] = nil
        else
            local listens = gameListens(r)
            if listens == true or (listens == nil and t - t0 >= REMOTE_GRACE) then
                ready[#ready + 1] = r
            end
        end
    end
    for _, r in ipairs(ready) do
        St.remoteWait[r] = nil
        hookRemote(r)
    end
end

function L.remoteWaiting()
    local n = 0
    for _ in pairs(St.remoteWait) do
        n = n + 1
    end
    return n
end

function L.remotes()
    St.remoteWait = own(setmetatable({}, { __mode = "k" }))
    St.connsOk = false
    local list = descendants(ReplicatedStorage)
    -- getconnections dianggap bisa dipercaya kalau minimal satu remote kelihatan punya listener
    if type(getconnections) == "function" then
        local n = 0
        for _, d in ipairs(list) do
            if EVENT_CLS[d.ClassName] then
                n = n + 1
                if n > 300 then
                    break
                end
                local sig = prop(d, "OnClientEvent")
                local ok, c = pcall(getconnections, sig)
                if sig ~= nil and ok and type(c) == "table" and #c > 0 then
                    St.connsOk = true
                    break
                end
            end
        end
    end
    for _, d in ipairs(list) do
        L.remote(d, false)
    end
    on(St.liveConns, prop(ReplicatedStorage, "DescendantAdded"), function(d)
        L.remote(d, true)
    end, "rs descendant")
end

-- Hook __namecall sekali saja (state di genv, dipakai ulang kalau script dijalankan lagi).
-- Di dalam hook TIDAK ada namecall sebelum old() (biar method namecall tidak ketimpa);
-- logging dikerjakan di thread lain via task.defer.
function L.outHook()
    if not (type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" and type(checkcaller) == "function") then
        St.outStatus = "off (hookmetamethod/getnamecallmethod/checkcaller missing)"
        return
    end
    local hs = genv.NoctisENIX_InspectorHook
    if type(hs) ~= "table" then
        hs = {}
        genv.NoctisENIX_InspectorHook = hs
    end
    if not hs.installed then
        local gnm, cc = getnamecallmethod, checkcaller
        local gcs = (type(getcallingscript) == "function" and getcallingscript) or nil
        local old, fallback
        -- ambil __namecall asli SEBELUM hook (cadangan kalau hookmetamethod tidak mengembalikan fungsi)
        if type(getrawmetatable) == "function" then
            local okM, mt = pcall(getrawmetatable, game)
            if okM and type(mt) == "table" then
                local okR, f = pcall(rawget, mt, "__namecall")
                if okR and type(f) == "function" then
                    fallback = f
                end
            end
        end
        local hook = function(self, ...)
            local sink = hs.sink
            if sink then
                -- fungsi executor di-pcall: kalau error di sini, SEMUA namecall game ikut gagal
                local okM, m = pcall(gnm)
                -- cuma task.defer: task.spawn bakal jalanin sink sekarang juga dan namecall di
                -- dalamnya (GetFullName dll) menimpa method yang mau dipanggil old().
                local defer = task.defer
                if okM and defer and (m == "FireServer" or m == "InvokeServer") then
                    local okC, isExec = pcall(cc)
                    if okC and not isExec then
                        local caller = nil
                        if gcs then
                            local okS, sc = pcall(gcs)
                            if okS then
                                caller = sc
                            end
                        end
                        pcall(defer, sink, self, m, caller, table.pack(...))
                    end
                end
            end
            local orig = old or fallback
            if orig then
                return orig(self, ...)
            end
            -- tidak ada __namecall asli sama sekali: panggil lewat __index (bukan namecall) biar game tetap jalan
            local okM2, m2 = pcall(gnm)
            if okM2 and type(m2) == "string" then
                return self[m2](self, ...)
            end
            return nil
        end
        if type(newcclosure) == "function" then
            local okW, wrapped = pcall(newcclosure, hook)
            if okW and type(wrapped) == "function" then
                hook = wrapped
            end
        end
        local okH, res = pcall(hookmetamethod, game, "__namecall", hook)
        if not okH then
            St.outStatus = "off (hookmetamethod error: " .. tostring(res) .. ")"
            return
        end
        old = (type(res) == "function" and res) or fallback
        hs.installed = true
        hs.noOrig = (old == nil)
    end
    if hs.noOrig then
        -- hook sudah terpasang dan tidak bisa dicabut; logging dimatikan, hook cuma meneruskan via __index
        St.outStatus = "off (hookmetamethod gave no original __namecall; hook only passes calls through)"
        return
    end
    local sinkFn = function(remote, method, caller, args)
        if not St.live then
            return
        end
        local cls = prop(remote, "ClassName")
        if cls ~= "RemoteEvent" and cls ~= "UnreliableRemoteEvent" and cls ~= "RemoteFunction" then
            return
        end
        local name = fullName(remote)
        local from = caller and (" from " .. fullName(caller)) or ""
        emit("REMOTE_OUT", "ROUT:" .. name, method .. " " .. name .. from .. " (" .. serArgs(args) .. ")")
    end
    St.sinkFn = sinkFn
    hs.sink = sinkFn
    St.outStatus = "on"
end

function L.prompts()
    if not ProximityPromptService then
        return
    end
    for _, ev in ipairs({ "PromptShown", "PromptTriggered", "PromptButtonHoldBegan", "PromptButtonHoldEnded", "PromptTriggerEnded" }) do
        on(St.liveConns, prop(ProximityPromptService, ev), function(pp, who)
            local extra = ""
            if typeof(who) == "Instance" then
                extra = " by " .. pname(who)
            end
            emit("PROMPT", "PROMPT:" .. ev .. ":" .. fullName(pp), ev .. " " .. promptInfo(pp) .. extra)
        end, "prompt " .. ev)
    end
end

function L.spawn()
    on(St.liveConns, prop(Workspace, "DescendantAdded"), function(d)
        local ln = string.lower(tostring(d.Name))
        local hit = false
        for _, w in ipairs(SPAWN_WORDS) do
            if string.find(ln, w, 1, true) then
                hit = true
                break
            end
        end
        if not hit then
            return
        end
        if not (isA(d, "BasePart") or isA(d, "Model") or isA(d, "Tool")) then
            return
        end
        -- tool yang dipegang sudah dicatat TOOL; part lain di karakter (darah, luka tusuk) tetap dicatat
        local owner = playerOf(d)
        if owner and isA(d, "Tool") then
            return
        end
        local a = attrsInline(d, 12)
        emit("SPAWN", "SPAWN:" .. ln, d.Name .. " [" .. d.ClassName .. "] at " .. posOf(d) .. " in " .. fullName(prop(d, "Parent"))
            .. (owner and (" [" .. pname(owner) .. "]") or "") .. (a ~= "" and (" {" .. a .. "}") or ""))
    end, "spawn")
end

-- Attribute pintu / locker / medkit / mayat + anak baru di folder itu.
function L.map()
    local n = 0
    for _, f in ipairs(findMapContainers(4, 3)) do
        if f.word ~= "map" then
            local c = f.inst
            local cname = fullName(c)
            L.attr(c, cname, "MAP")
            on(St.liveConns, prop(c, "ChildAdded"), function(ch)
                local a = attrsInline(ch, 12)
                emit("MAP", "MAPADD:" .. cname, "+ " .. ch.Name .. " [" .. ch.ClassName .. "] in " .. cname .. (a ~= "" and (" {" .. a .. "}") or ""))
            end, "map child")
            for _, d in ipairs(children(c)) do
                if n >= 400 then
                    break
                end
                n = n + 1
                L.attr(d, fullName(d), "MAP")
                local extra = 0
                for _, sub in ipairs(descendants(d)) do
                    if extra >= 5 or n >= 400 then
                        break
                    end
                    if attrsInline(sub, 1) ~= "" then
                        extra = extra + 1
                        n = n + 1
                        L.attr(sub, fullName(sub), "MAP")
                    end
                end
            end
        end
    end
end

-- Diff teks PlayerGui yang kelihatan (cuma teks baru / berubah).
-- UI template (daftar pemain / vote / role) sering punya banyak elemen dengan full name SAMA, jadi per
-- full name disimpan himpunan teks: teks dianggap baru kalau belum ada di himpunan scan sebelumnya.
-- (Tidak di-key per Instance: daftar yang dibangun ulang tiap update bakal ke-log ulang semua.)
function L.guiScan()
    local pg = childOfClass(LocalPlayer, "PlayerGui")
    if not pg then
        return
    end
    local items = collectTexts(pg, 3000, St.gui)
    local cur = own({})
    local prev = St.guiPrev
    local fresh = {}
    local t = now()
    for _, it in ipairs(items) do
        local key = fullName(it[1])
        local txt = it[2]
        local set = cur[key]
        if not set then
            -- teks bisa sama dengan nama pemain: tandai own() biar tidak muncul di probe getgc
            set = own({ t = own({}), s = own({}) })
            cur[key] = set
        end
        if not set.t[txt] then
            local shape = string.gsub(txt, "%d", "#")
            set.t[txt] = true
            set.s[shape] = true
            local old = prev and prev[key]
            if prev and not (old and old.t[txt]) then
                local skip = false
                -- timer / hitungan yang cuma ganti angka: maksimal sekali per 15 detik per bentuk teks
                if old and old.s[shape] then
                    local tk = key .. "\n" .. shape
                    if t - (St.guiTick[tk] or -1000) < 15 then
                        skip = true
                    else
                        if St.guiTick[tk] == nil then
                            St.guiTickN = (St.guiTickN or 0) + 1
                            if St.guiTickN > 4000 then
                                St.guiTick = own({})
                                St.guiTickN = 1
                            end
                        end
                        St.guiTick[tk] = t
                    end
                end
                if not skip then
                    fresh[#fresh + 1] = { key, txt }
                end
            end
        end
    end
    St.guiPrev = cur
    for i, f in ipairs(fresh) do
        if i > 30 then
            emit("GUI", "GUI:more", "... +" .. (#fresh - 30) .. " more new texts")
            break
        end
        emit("GUI", "GUI:" .. f[1], f[1] .. ": " .. q(f[2], 200))
    end
end

-- LIGHT: coalescing per instance+property. Record kind "prop" (nilai dibaca ulang saat ditulis)
-- atau "event" (fmt(obj) kejadian terakhir, baru diformat saat ditulis: burst DescendantAdded murah).
-- Update dalam LIGHT_COALESCE dtk sejak baris terakhir dilewati dan dihitung; baris berikutnya
-- (update baru atau flush dari Heartbeat) menyebut jumlahnya.
local function coRec(inst, key, kind, fmt)
    local per = St.lightCo[inst]
    if per == nil then
        per = own({})
        St.lightCo[inst] = per
    end
    local c = per[key]
    if c == nil then
        c = own({ inst = inst, key = key, kind = kind, fmt = fmt, t = -1e9, skip = 0 })
        if kind == "prop" then
            c.last = prop(inst, key)
        end
        per[key] = c
    end
    return c
end

local function coEmit(c, t)
    St.lightPend[c] = nil
    local label = lightLabel(c.inst)
    local text
    if c.kind == "prop" then
        local v = prop(c.inst, c.key)
        text = label .. " " .. c.key .. " = " .. show(v) .. "  (was " .. show(c.last) .. ")"
        c.last = v
    else
        local okF, s = pcall(c.fmt, c.obj)
        text = label .. " " .. (okF and tostring(s) or ("? (" .. tostring(s) .. ")"))
    end
    if c.skip > 0 then
        text = text .. "  (+" .. c.skip .. " updates coalesced)"
    end
    c.t, c.skip = t, 0
    emit("LIGHT", "LIGHT:" .. label .. ":" .. c.key, text, LIGHT_RATE_MAX)
end

-- obj: subjek kejadian terbaru (record "event"); nil untuk record "prop".
local function coHit(c, obj)
    if obj ~= nil then
        c.obj = obj
    end
    local t = now()
    if t - c.t < LIGHT_COALESCE then
        c.skip = c.skip + 1
        St.lightPend[c] = true
        return
    end
    coEmit(c, t)
end

-- Tulis baris penutup untuk update yang dilewati (window sudah lewat, atau semua kalau force).
function L.lightFlush(force)
    local t = now()
    local due = {}
    for c in pairs(St.lightPend) do
        if force or t - c.t >= LIGHT_COALESCE then
            due[#due + 1] = c
        end
    end
    for _, c in ipairs(due) do
        coEmit(c, t)
    end
end

-- Hook daftar property satu instance (sekali per instance, total dibatasi LIGHT_HOOK_CAP).
function L.lightInst(inst, list)
    if typeof(inst) ~= "Instance" or type(list) ~= "table" then
        return
    end
    if St.lightN >= LIGHT_HOOK_CAP then
        if not St.lightCapped then
            St.lightCapped = true
            emit("LIGHT", "LIGHTCAP", "hook cap reached (" .. LIGHT_HOOK_CAP .. " instances); later Lighting / Emp* instances are not watched", LIGHT_RATE_MAX)
        end
        return
    end
    if not once(inst, "light") then
        return
    end
    St.lightN = St.lightN + 1
    for _, k in ipairs(list) do
        local sig = propSig(inst, k)
        if sig ~= nil then
            local c = coRec(inst, k, "prop")
            on(St.liveConns, sig, function()
                coHit(c)
            end, "light " .. k)
        end
    end
end

-- Lighting / CurrentCamera: anak yang ada sekarang (baris "baseline"), anak baru / hilang, property efek.
function L.lightBox(box, why)
    if typeof(box) ~= "Instance" or not once(box, "lightbox") then
        return
    end
    local bname = fullName(box)
    local kids = children(box)
    if #kids == 0 then
        emit("LIGHT", "LIGHTBASE:" .. bname, why .. " " .. bname .. ": no children", LIGHT_RATE_MAX)
    end
    for i, c in ipairs(kids) do
        if i > 30 then
            emit("LIGHT", "LIGHTBASE:" .. bname, why .. " " .. bname .. " child: ... +" .. (#kids - 30) .. " more", LIGHT_RATE_MAX)
            break
        end
        emit("LIGHT", "LIGHTBASE:" .. bname, why .. " " .. bname .. " child: " .. fxLine(c), LIGHT_RATE_MAX)
    end
    for _, c in ipairs(kids) do
        L.lightInst(c, fxPropList(c))
    end
    on(St.liveConns, prop(box, "ChildAdded"), function(c)
        emit("LIGHT", "LIGHTCHILD:" .. bname, "+ " .. fxLine(c) .. " in " .. bname, LIGHT_RATE_MAX)
        L.lightInst(c, fxPropList(c))
    end, "light child+")
    on(St.liveConns, prop(box, "ChildRemoved"), function(c)
        emit("LIGHT", "LIGHTCHILD:" .. bname, "- " .. tostring(prop(c, "Name")) .. " [" .. tostring(prop(c, "ClassName")) .. "] from " .. bname, LIGHT_RATE_MAX)
    end, "light child-")
end

-- Satu ScreenGui Emp*: Enabled/DisplayOrder, Visible/transparansi/warna isinya, dan isi baru.
function L.empGui(g, why)
    if typeof(g) ~= "Instance" or not once(g, "empgui") then
        return
    end
    local gname = tostring(prop(g, "Name"))
    emit("LIGHT", "LIGHTGUI:" .. gname, why .. " gui " .. empGuiLine(g), LIGHT_RATE_MAX)
    L.lightInst(g, { "Enabled", "DisplayOrder" })
    local n = 0
    local function hookDesc(d)
        local list = guiPropList(d)
        if list and n < EMP_GUI_HOOK_CAP then
            n = n + 1
            L.lightInst(d, list)
        end
    end
    for _, d in ipairs(descendants(g)) do
        hookDesc(d)
    end
    local added = coRec(g, "DescendantAdded", "event", function(d)
        local p = propsInline(d, EMP_TREE_PROPS)
        return "+ " .. tostring(prop(d, "Name")) .. " [" .. tostring(prop(d, "ClassName")) .. "]" .. (p ~= "" and (" " .. p) or "")
    end)
    on(St.liveConns, prop(g, "DescendantAdded"), function(d)
        coHit(added, d)
        hookDesc(d)
    end, "emp gui desc+")
end

function L.empGuis()
    local pg = childOfClass(LocalPlayer, "PlayerGui")
    if not pg then
        emit("LIGHT", "LIGHTGUI", "PlayerGui not found; Emp* guis not hooked", LIGHT_RATE_MAX)
        return
    end
    local n = 0
    for _, g in ipairs(children(pg)) do
        if isEmpGui(g) then
            n = n + 1
            L.empGui(g, "baseline")
        end
    end
    if n == 0 then
        emit("LIGHT", "LIGHTGUI", "baseline: no Emp* ScreenGui in PlayerGui yet", LIGHT_RATE_MAX)
    end
    -- ScreenGui ResetOnSpawn dibuat ulang tiap respawn
    on(St.liveConns, prop(pg, "ChildAdded"), function(g)
        if isEmpGui(g) then
            L.empGui(g, "+")
        end
    end, "emp gui+")
    on(St.liveConns, prop(pg, "ChildRemoved"), function(g)
        if isEmpGui(g) then
            local gname = tostring(prop(g, "Name"))
            emit("LIGHT", "LIGHTGUI:" .. gname, "- gui " .. gname .. " removed from PlayerGui", LIGHT_RATE_MAX)
        end
    end, "emp gui-")
end

function L.lighting()
    if Lighting then
        emit("LIGHT", "LIGHTBASE:Lighting", "baseline Lighting " .. propsInline(Lighting, LIGHT_PROPS), LIGHT_RATE_MAX)
        L.lightInst(Lighting, LIGHT_PROPS)
        L.lightBox(Lighting, "baseline")
    end
    L.lightBox(prop(Workspace, "CurrentCamera"), "baseline")
    on(St.liveConns, propSig(Workspace, "CurrentCamera"), function()
        local cam = prop(Workspace, "CurrentCamera")
        emit("LIGHT", "LIGHTCAM", "CurrentCamera -> " .. fullName(cam), LIGHT_RATE_MAX)
        L.lightBox(cam, "new camera")
    end, "light camera")
    L.empGuis()
end

----------------------------------------------------------------------
-- Snapshot sections: { key, title, fn(out, X) }
----------------------------------------------------------------------
local function attrLine(out, label, inst)
    if inst == nil then
        return
    end
    local a = attrsInline(inst, 200)
    out(label .. (a ~= "" and a or "(none)"))
end

local function dumpPlayer(out, p, X)
    local name = pname(p)
    out("-- " .. name .. "  display=" .. q(tostring(prop(p, "DisplayName"))) .. " userId=" .. tostring(prop(p, "UserId"))
        .. " team=" .. teamName(p) .. " neutral=" .. tostring(prop(p, "Neutral")) .. ((p == LocalPlayer) and "  (YOU)" or ""))
    local ch = prop(p, "Character")
    local hum = childOfClass(ch, "Humanoid")
    local hrp = findChild(ch, "HumanoidRootPart")
    attrLine(out, "  Player attrs: ", p)
    attrLine(out, "  Character attrs: ", ch)
    attrLine(out, "  Humanoid attrs: ", hum)
    attrLine(out, "  HRP attrs: ", hrp)
    if not ch then
        out("  (no character)")
    end
    if hum then
        local okS, st = pcall(hum.GetState, hum)
        out("  Humanoid: Health=" .. num(prop(hum, "Health")) .. "/" .. num(prop(hum, "MaxHealth")) .. " WalkSpeed=" .. num(prop(hum, "WalkSpeed"))
            .. " State=" .. (okS and enumName(st) or "?") .. " Sit=" .. tostring(prop(hum, "Sit")) .. " PlatformStand=" .. tostring(prop(hum, "PlatformStand"))
            .. " DisplayName=" .. q(tostring(prop(hum, "DisplayName"))))
    end
    if hrp then
        out("  Position: " .. v3s(prop(hrp, "Position")) .. " Anchored=" .. tostring(prop(hrp, "Anchored")))
    end
    local pc = {}
    for _, c in ipairs(children(p)) do
        local s = c.ClassName .. " " .. c.Name
        if isA(c, "ValueBase") then
            s = s .. " = " .. show(prop(c, "Value"))
        end
        pc[#pc + 1] = s
        if c.ClassName == "Folder" or c.ClassName == "Configuration" then
            for _, v in ipairs(children(c)) do
                pc[#pc + 1] = "  " .. c.Name .. "." .. v.Name .. " [" .. v.ClassName .. "]" .. (isA(v, "ValueBase") and (" = " .. show(prop(v, "Value"))) or "")
            end
        end
    end
    out("  Player children: " .. (#pc > 0 and table.concat(pc, "; ") or "(none)"))
    if ch then
        local items = {}
        for _, d in ipairs(descendants(ch)) do
            local cls = d.ClassName
            local par = prop(d, "Parent")
            if cls == "Tool" then
                local a = attrsInline(d, 10)
                items[#items + 1] = "Tool " .. q(d.Name) .. (a ~= "" and (" {" .. a .. "}") or "")
            elseif (par == ch or par == hum or par == hrp) and isA(d, "ValueBase") then
                items[#items + 1] = cls .. " " .. d.Name .. " = " .. show(prop(d, "Value"))
            elseif par == ch and (cls == "LocalScript" or cls == "Script" or cls == "ModuleScript") then
                items[#items + 1] = cls .. " " .. d.Name
            elseif cls == "BillboardGui" or cls == "SurfaceGui" then
                local texts = {}
                for _, tl in ipairs(descendants(d)) do
                    if TEXTCLS[tl.ClassName] then
                        local tx = prop(tl, "Text")
                        if type(tx) == "string" and tx ~= "" then
                            texts[#texts + 1] = q(stripRich(tx), 80) .. ((prop(tl, "Visible") == false) and "(hidden)" or "")
                        end
                    end
                end
                items[#items + 1] = cls .. " " .. d.Name .. " enabled=" .. tostring(prop(d, "Enabled")) .. " texts: " .. table.concat(texts, ", ")
            elseif cls == "Highlight" then
                items[#items + 1] = "Highlight " .. d.Name .. " enabled=" .. tostring(prop(d, "Enabled")) .. " fill=" .. show(prop(d, "FillColor")) .. " outline=" .. show(prop(d, "OutlineColor"))
            end
        end
        out("  Character items: " .. (#items > 0 and table.concat(items, "; ") or "(none)"))
        local animator = childOfClass(hum, "Animator")
        if animator then
            local okT, tracks = pcall(animator.GetPlayingAnimationTracks, animator)
            local ts = {}
            if okT and type(tracks) == "table" then
                for _, tr in ipairs(tracks) do
                    local a = prop(tr, "Animation")
                    local id = normId(a and prop(a, "AnimationId") or nil)
                    ts[#ts + 1] = tostring(a and prop(a, "Name") or prop(tr, "Name")) .. "(" .. tostring(id) .. " -> " .. tostring(id and St.animNames[id] or "?") .. ")"
                end
            end
            out("  Playing anims: " .. (#ts > 0 and table.concat(ts, ", ") or "(none)"))
        end
    end
    if CollectionService then
        local okA, ta = pcall(CollectionService.GetTags, CollectionService, p)
        local okB, tb = pcall(CollectionService.GetTags, CollectionService, ch)
        out("  Tags player: " .. ((okA and type(ta) == "table" and #ta > 0) and table.concat(ta, ", ") or "(none)")
            .. " | character: " .. ((ch and okB and type(tb) == "table" and #tb > 0) and table.concat(tb, ", ") or "(none)"))
    end
end

local SECTIONS = {
