    { "network", "GAME NETWORK (ServiceNetworks / RoleNetworks getters)", function(out, X)
        local SN = findChild(ReplicatedStorage, "ServiceNetworks")
        local RN = findChild(ReplicatedStorage, "RoleNetworks")
        out("ServiceNetworks: " .. (SN and "found" or "missing") .. "   RoleNetworks: " .. (RN and "found" or "missing"))
        if X.opts.noNetwork then
            out("(network probe skipped)")
            return
        end
        out("Calls only read-style getters the game client itself uses. Never calls on*/toggle*/set*/vote*/... actions.")
        local function invoke(remote, timeout)
            if not (remote and isA(remote, "RemoteFunction")) then
                return false, "missing"
            end
            local box = { done = false }
            task.spawn(function()
                local res = table.pack(pcall(function()
                    return remote:InvokeServer()
                end))
                box.res, box.done = res, true
            end)
            local waited = 0
            while not box.done and waited < (timeout or 3) do
                local dt = task.wait(0.05)
                waited = waited + ((type(dt) == "number" and dt > 0) and dt or 0.05)
            end
            if not box.done then
                return false, "timeout (no answer in " .. tostring(timeout or 3) .. "s; probably server->client)"
            end
            if not box.res[1] then
                return false, "error: " .. tostring(box.res[2])
            end
            local parts = {}
            for i = 2, box.res.n do
                local okS, str = pcall(ser, box.res[i], 5)
                str = okS and tostring(str) or show(box.res[i])
                if #str > 4000 then
                    str = string.sub(str, 1, 4000) .. " ...(cut)"
                end
                parts[#parts + 1] = str
            end
            return true, (#parts > 0 and table.concat(parts, ", ") or "(no values)")
        end
        local GETTERS = {
            { "roleService", "role" }, { "teamService", "teamMembers" }, { "gameService", "gamePhase" },
            { "gameService", "gameStarted" }, { "gameService", "players" }, { "gameService", "talliedVotes" },
            { "gameService", "abilitiesEnabled" }, { "gameService", "canVote" }, { "spectatingService", "spectatableTargets" },
            { "chatService", "taggifiedPlayers" }, { "chatService", "generalEnabled" }, { "highlightsService", "highlights" },
            { "veilChargesService", "charges" }, { "terrorService", "terror" }, { "corruptionService", "corruption" },
            { "perksService", "equippedVeilPerk" }, { "perksService", "equippedPositivePerk" }, { "perksService", "equippedNegativePerk" },
        }
        local roleFolder = nil
        for _, g in ipairs(GETTERS) do
            local svc = SN and findChild(SN, g[1])
            local r = svc and findChild(svc, g[2])
            local ok, text = invoke(r, 3)
            out(string.format("  %s.%s -> %s", g[1], g[2], tostring(text)))
            if ok and g[2] == "role" and not roleFolder then
                local low = string.lower(text)
                if RN then
                    for _, f in ipairs(children(RN)) do
                        if string.find(low, string.lower(f.Name), 1, true) then
                            roleFolder = f
                            break
                        end
                    end
                end
            end
        end
        if not RN then
            return
        end
        local names = {}
        for _, f in ipairs(children(RN)) do
            names[#names + 1] = f.Name
        end
        table.sort(names)
        out("RoleNetworks folders: " .. table.concat(names, ", "))
        if not roleFolder then
            out("Own role folder not identified (role getter gave no match); skipping role getters.")
            return
        end
        out("Own role folder: " .. roleFolder.Name)
        local SAFE = { "^can", "^get", "^is", "^has", "teammembers", "protectee", "patients", "toignore", "ballots", "state$", "ready$", "vigilantes", "info$", "charges" }
        local DENY = { "^on", "^toggle", "^set", "^activate", "^deactivate", "^claim", "^detonate", "^swap", "^convert", "^run", "^vote", "^pick", "^skip", "^request", "^reset", "^clear", "^give", "^take", "^mark", "^report", "^teleport", "^self", "^drop", "^lock", "^unlock" }
        for _, r in ipairs(children(roleFolder)) do
            local ln = string.lower(r.Name)
            local denied = false
            for _, pat in ipairs(DENY) do
                if string.find(ln, pat) then
                    denied = true
                    break
                end
            end
            local safe = false
            for _, pat in ipairs(SAFE) do
                if string.find(ln, pat) then
                    safe = true
                    break
                end
            end
            if isA(r, "RemoteFunction") and safe and not denied then
                local _, text = invoke(r, 3)
                out(string.format("  %s.%s -> %s", roleFolder.Name, r.Name, tostring(text)))
            else
                out(string.format("  %s.%s (%s, not called)", roleFolder.Name, r.Name, r.ClassName))
            end
        end
