            out("(decompile skipped)")
            return
        end
        if type(decompile) ~= "function" then
            out("decompile: not available on this executor")
            return
        end
        local TARGETS = {
            "client.controllers.roleController.roles.mafia",
            "client.controllers.roleController.roles.doctor",
            "client.controllers.roleController",
            "client.controllers.interactionController",
        }
        for _, path in ipairs(TARGETS) do
            local inst = resolve(path, X.desc)
            out("")
            out("--- " .. path .. " -> " .. (inst and fullName(inst) or "not found"))
            if inst then
                local box = { done = false }
                task.spawn(function()
                    local ok, src = pcall(decompile, inst)
                    box.ok, box.src, box.done = ok, src, true
                end)
                local waited = 0
                while not box.done and waited < 15 do
                    local dt = task.wait(0.1)
                    waited = waited + ((type(dt) == "number" and dt > 0) and dt or 0.1)
                end
                if not box.done then
                    out("  decompile: timeout (15s)")
                elseif not box.ok or type(box.src) ~= "string" then
                    out("  decompile: error " .. tostring(box.src))
                else
                    local lines = {}
                    for line in string.gmatch(box.src .. "\n", "([^\n]*)\n") do
                        lines[#lines + 1] = line
                    end
                    -- Ringkasan: baris yang memanggil remote / handler penting (+-3 baris konteks)
                    out("  lines: " .. #lines .. "  (key calls below, then source)")
                    for i, line in ipairs(lines) do
                        local l = string.lower(line)
                        if string.find(l, "invokeserver", 1, true) or string.find(l, "fireserver", 1, true)
                            or string.find(l, "onstab", 1, true) or string.find(l, "onshoot", 1, true)
                            or string.find(l, "onheal", 1, true) or string.find(l, "handlemafiastab", 1, true)
                            or string.find(l, "settargetcharacter", 1, true) or string.find(l, "bindaction", 1, true) then
                            out(string.format("  >> %d: %s", i, line))
                        end
                    end
                    local cap = math.min(#lines, 1500)
                    for i = 1, cap do
                        out(string.format("  %4d| %s", i, lines[i]))
                    end
                    if #lines > cap then
                        out("  ... (" .. (#lines - cap) .. " more lines cut)")
                    end
                end
            end
        end
    end },
}

----------------------------------------------------------------------
-- API
----------------------------------------------------------------------
local API = own({ version = VERSION })
local UI = own({})

-- Status panel langsung ikut berubah kalau API dipanggil dari luar UI.
local function touchUI()
    if St.alive and UI.refresh then
        pcall(UI.refresh)
    end
end

local function runSnapshot(opts)
    local lines = {}
    local function out(s)
        lines[#lines + 1] = tostring(s)
    end
    St.snapN = St.snapN + 1
    out("######## SNAPSHOT #" .. St.snapN .. "  " .. dateStr() .. (St.liveT0 and ("  live " .. stamp()) or "") .. " ########")
    local X = { desc = {}, opts = opts }
    X.ws = function()
        if not X.wsList then
            X.wsList = descendants(Workspace)
        end
        return X.wsList
    end
    for i, sec in ipairs(SECTIONS) do
        out("")
        out(string.format("==== [%d] %s ====", i, sec[2]))
        local t0 = os.clock()
        local ok, err = pcall(sec[3], out, X)
        if not ok then
            out("[" .. sec[1] .. "] ERROR: " .. tostring(err))
        end
        out(string.format("(%s took %.2fs)", sec[1], os.clock() - t0))
        -- yield antar section: snapshot berat, jangan sampai kena script timeout / freeze lama
        task.wait()
    end
    St.snaps[#St.snaps + 1] = lines
    while #St.snaps > 3 do
        table.remove(St.snaps, 1)
    end
    if St.live then
        push(stamp() .. " SNAPSHOT #" .. St.snapN .. " taken (" .. #lines .. " lines)")
    end
    return #lines
end

-- Boleh yield (require, GetProductInfo). opts.noRequire = true -> tidak require modul game.
function API.snapshot(opts)
    if not St.alive then
        return false, "unloaded"
    end
    if St.busy then
        return false, "busy"
    end
    St.busy = true
    local ok, res = pcall(runSnapshot, (type(opts) == "table" and opts) or {})
    St.busy = false
    if not ok then
        noteErr("snapshot", res)
        return false, tostring(res)
    end
    touchUI()
    return true, res
end

function API.startLive()
    if not St.alive then
        return false, "unloaded"
    end
    if St.live then
        return true, "already running"
    end
    St.live = true
    St.liveT0 = St.liveT0 or now()
    St.sessions = St.sessions + 1
    push(stamp() .. " LIVE started (session " .. St.sessions .. ")")
    local steps = {
        { "anim scan", L.scanAnims },
        { "players", L.players },
        { "globals", L.globals },
        { "tags", function()
            for _, t in ipairs(PRE_TAGS) do
                L.hookTag(t)
            end
            L.tags()
        end },
        { "chat", L.chat },
        { "remotes", L.remotes },
        { "remote out", L.outHook },
        { "prompts", L.prompts },
        { "spawn", L.spawn },
        { "map", L.map },
        { "gui", function()
            St.guiPrev = nil
            L.guiScan()
        end },
        { "lighting", L.lighting },
    }
    for _, s in ipairs(steps) do
        local ok, err = pcall(s[2])
        if not ok then
            noteErr("startLive " .. s[1], err)
        end
    end
    local t = now()
    St.tGui, St.tTags, St.tFlush = t, t, t
    push(stamp() .. " LIVE hooks: " .. #St.liveConns .. " connections, remote in: " .. St.remoteN .. " hooked, " .. L.remoteWaiting()
        .. " waiting for a game listener, remote out: " .. tostring(St.outStatus))
    touchUI()
    return true, "started"
end

function API.stopLive()
    if not St.live then
        return true, "not running"
    end
    -- nilai akhir tween yang masih ditahan coalescing ditulis dulu
    local okF, errF = pcall(L.lightFlush, true)
    if not okF then
        noteErr("light flush", errF)
    end
    flushRate(true)
    push(stamp() .. " LIVE stopped")
    St.live = false
    for _, c in ipairs(St.liveConns) do
        pcall(function()
            c:Disconnect()
        end)
    end
    St.liveConns = {}
    St.hk = own(setmetatable({}, { __mode = "k" }))
    St.tagHooked = own({})
    St.tagN, St.remoteN = 0, 0
    St.remoteWait = own(setmetatable({}, { __mode = "k" }))
    St.guiPrev = nil
    St.lightCo = own(setmetatable({}, { __mode = "k" }))
    St.lightPend = own({})
    St.lightN = 0
    St.lightCapped = false
    local hs = genv.NoctisENIX_InspectorHook
    if type(hs) == "table" and hs.sink == St.sinkFn then
        hs.sink = nil
    end
    touchUI()
    return true, "stopped"
end

function API.lines()
    local n = St.count
    for _, s in ipairs(St.snaps) do
        n = n + #s
    end
    return n
end

function API.text()
    if St.live then
        flushRate(true)
    end
    local parts = {}
    local function add(s)
        parts[#parts + 1] = s
    end
    add("NoctisENIX Inspector v" .. VERSION)
    add("date: " .. dateStr())
    add("executor: " .. execName())
    add("PlaceId: " .. tostring(prop(game, "PlaceId")) .. "  GameId: " .. tostring(prop(game, "GameId")) .. "  JobId: " .. tostring(prop(game, "JobId")))
    add("local player: " .. pname(LocalPlayer))
    add("snapshots kept: " .. #St.snaps .. " (taken " .. St.snapN .. ")")
    add("live log: " .. St.count .. " lines kept, " .. St.dropped .. " oldest dropped (cap " .. St.cap .. "), running: " .. tostring(St.live))
    add("remote out hook: " .. tostring(St.outStatus or "not started"))
    add("note: the module probe requires game ModuleScripts; requiring controllers can have side effects.")
    add("note: REMOTE_IN connects a remote only once the game listens to it (getconnections) or " .. REMOTE_GRACE
        .. "s after it appears, so events queued for late game listeners still reach the game.")
    add("note: LIGHT lines (Lighting, Lighting/Camera effects, Emp* ScreenGuis) log at most one line per instance+property per "
        .. LIGHT_COALESCE .. "s; '(+N updates coalesced)' = N changes folded into that line, which shows the current value.")
    add("")
    if #St.snaps == 0 then
        add("(no snapshot taken)")
        add("")
    end
    for _, s in ipairs(St.snaps) do
        for _, l in ipairs(s) do
            add(l)
        end
        add("")
    end
    add("==== LIVE LOG ====")
    for _, l in ipairs(logLines()) do
        add(l)
    end
    if #St.errs > 0 then
        add("")
        add("==== INSPECTOR ERRORS ====")
        for _, e in ipairs(St.errs) do
            add(e)
        end
    end
    return table.concat(parts, "\n")
end

-- Boleh yield (snapshot otomatis kalau belum ada). Return ok, info (path / "clipboard only" / "console").
function API.save()
    -- snapshot lagi jalan (tombol Snapshot lalu Save cepat)? tunggu dulu, maks 30 dtk
    local w0 = os.clock()
    while St.busy and os.clock() - w0 < 30 do
        task.wait(0.1)
    end
    if #St.snaps == 0 and St.alive then
        API.snapshot()
    end
    local okT, txt = pcall(API.text)
    if not okT then
        return false, "text failed: " .. tostring(txt)
    end
    local path, werr = nil, nil
    local wf = writefile
    if type(wf) == "function" then
        local isf, mkf = isfolder, makefolder
        local exists = false
        if type(isf) == "function" then
            local okI, r = pcall(isf, "NoctisENIX")
            exists = okI and r == true
        end
        if not exists and type(mkf) == "function" then
            pcall(mkf, "NoctisENIX")
        end
        local fname = "inspector_" .. tostring(prop(game, "PlaceId")) .. "_" .. tostring(os.time()) .. ".txt"
        local okW, e = pcall(wf, "NoctisENIX/" .. fname, txt)
        if okW then
            path = "NoctisENIX/" .. fname
        else
            -- folder gagal dibuat? coba di root workspace executor
            local okW2, e2 = pcall(wf, fname, txt)
            if okW2 then
                path = fname
            else
                werr = tostring(e) .. " / " .. tostring(e2)
            end
        end
    end
    local clip = setclipboard or toclipboard
    local clipped = false
    if type(clip) == "function" then
        clipped = (pcall(clip, txt))
    end
    if path then
        St.lastSave = path .. (clipped and " + clipboard" or "")
    elseif clipped then
        St.lastSave = "clipboard only"
    else
        local chunks = 0
        for i = 1, #txt, 3000 do
            chunks = chunks + 1
            print(string.sub(txt, i, i + 2999))
        end
        St.lastSave = "console (" .. chunks .. " chunks)"
    end
    if werr then
        noteErr("writefile", werr)
    end
    St.savedMark = St.pushed + St.snapN
    touchUI()
    return true, St.lastSave
end

function API.unload()
    if not St.alive then
        return true, "already unloaded"
    end
    pcall(API.stopLive)
    St.alive = false
    for _, c in ipairs(St.uiConns) do
        pcall(function()
            c:Disconnect()
        end)
    end
    St.uiConns = {}
    if St.gui then
        pcall(function()
            St.gui:Destroy()
        end)
    end
    if genv.NoctisENIX_Inspector == API then
        genv.NoctisENIX_Inspector = nil
    end
    return true, "unloaded"
end

-- Kait buat test / power user.
API._test = {
    setClock = function(fn)
        clockFn = fn or os.clock
    end,
    push = function(cat, text)
        push(stamp() .. " " .. tostring(cat) .. " " .. tostring(text))
    end,
    gui = function()
        return St.gui
    end,
    buttons = function()
        return UI.buttons
    end,
    state = function()
        return St
    end,
    mount = function(g)
        return UI.mount(g)
    end,
}

----------------------------------------------------------------------
-- UI
----------------------------------------------------------------------
local function new(class, props, parent)
    local inst = Instance.new(class)
    for k, v in pairs(props) do
        pcall(setp, inst, k, v)
    end
    if parent then
        inst.Parent = parent
    end
    return inst
end

function UI.mount(gui)
    local targets = {}
    if type(gethui) == "function" then
        local ok, h = pcall(gethui)
        if ok and typeof(h) == "Instance" then
            targets[#targets + 1] = h
        end
    end
    if CoreGui then
        targets[#targets + 1] = CoreGui
    end
    local pg = childOfClass(LocalPlayer, "PlayerGui")
    if not pg then
        local ok, r = pcall(LocalPlayer.WaitForChild, LocalPlayer, "PlayerGui", 5)
        pg = ok and r or nil
    end
    if pg then
        targets[#targets + 1] = pg
    end
    for _, t in ipairs(targets) do
        local ok = pcall(setp, gui, "Parent", t)
        -- jangan bandingkan Parent == t: CoreGui / gethui() hasil cloneref tidak == referensi kanonik
        -- yang dikembalikan .Parent, padahal parenting-nya berhasil
        if ok and prop(gui, "Parent") ~= nil then
            return t
        end
    end
    return nil
end

function UI.setInfo(text)
    if UI.info then
        pcall(setp, UI.info, "Text", tostring(text))
    end
end

function UI.refresh()
    if not UI.status then
        return
    end
    pcall(setp, UI.status, "Text", string.format("Lines: %d  |  Live: %s  |  Save: %s", API.lines(), St.live and "ON" or "off", tostring(St.lastSave or "-")))
    pcall(setp, UI.liveBtn, "Text", St.live and "Stop live log" or "Start live log")
    pcall(setp, UI.liveBtn, "BackgroundColor3", St.live and Color3.fromRGB(168, 85, 247) or Color3.fromRGB(30, 27, 46))
    pcall(setp, UI.lastLbl, "Text", tostring(St.last or "(no live events yet)"))
end

function UI.build()
    local colBg, colPanel, colElem = Color3.fromRGB(13, 12, 20), Color3.fromRGB(20, 18, 32), Color3.fromRGB(30, 27, 46)
    local colAccent, colText, colSub = Color3.fromRGB(168, 85, 247), Color3.fromRGB(236, 232, 248), Color3.fromRGB(150, 144, 176)
    local gui = new("ScreenGui", { Name = "NoctisENIX_Inspector", ResetOnSpawn = false, DisplayOrder = 1000, IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling }, nil)
    St.gui = gui
    UI.mount(gui)
    local main = new("Frame", { Name = "Main", Size = UDim2.fromOffset(340, 236), Position = UDim2.new(0, 24, 0.5, -118), BackgroundColor3 = colBg, BorderSizePixel = 0, Active = true }, gui)
    new("UICorner", { CornerRadius = UDim.new(0, 8) }, main)
    new("UIStroke", { Color = colAccent, Thickness = 1.2, Transparency = 0.35 }, main)
    local title = new("TextLabel", {
        Name = "Title", Size = UDim2.new(1, 0, 0, 28), BackgroundColor3 = colPanel, BorderSizePixel = 0, Active = true,
        Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = colText, Text = "NoctisENIX Inspector",
    }, main)
    new("UICorner", { CornerRadius = UDim.new(0, 8) }, title)
    UI.status = new("TextLabel", {
        Name = "Status", Position = UDim2.fromOffset(10, 32), Size = UDim2.new(1, -20, 0, 18), BackgroundTransparency = 1,
        Font = Enum.Font.GothamSemibold, TextSize = 12, TextColor3 = colText, TextXAlignment = Enum.TextXAlignment.Left, Text = "",
    }, main)
    UI.info = new("TextLabel", {
        Name = "Info", Position = UDim2.fromOffset(10, 52), Size = UDim2.new(1, -20, 0, 44), BackgroundTransparency = 1,
        Font = Enum.Font.Gotham, TextSize = 12, TextColor3 = colSub, TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, Text = HELP_TEXT,
    }, main)
    local function button(text, x, y)
        local b = new("TextButton", {
            Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(155, 28), BackgroundColor3 = colElem, BorderSizePixel = 0,
            AutoButtonColor = true, Font = Enum.Font.GothamSemibold, TextSize = 13, TextColor3 = colText, Text = text,
        }, main)
        new("UICorner", { CornerRadius = UDim.new(0, 6) }, b)
        return b
    end
    local snapBtn = button("Snapshot", 10, 100)
    UI.liveBtn = button("Start live log", 175, 100)
    local saveBtn = button("Save (file + clipboard)", 10, 134)
    local closeBtn = button("Close", 175, 134)
    UI.lastLbl = new("TextLabel", {
        Name = "Last", Position = UDim2.fromOffset(10, 168), Size = UDim2.new(1, -20, 0, 60), BackgroundTransparency = 1,
        Font = Enum.Font.Code, TextSize = 11, TextColor3 = colSub, TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, Text = "",
    }, main)
    UI.buttons = { snapshot = snapBtn, live = UI.liveBtn, save = saveBtn, close = closeBtn }

    on(St.uiConns, prop(snapBtn, "MouseButton1Click"), function()
        if St.busy then
            return
        end
        UI.setInfo("Snapshot running... (can take a few seconds)")
        task.spawn(function()
            local ok, n = API.snapshot()
            UI.setInfo(ok and ("Snapshot done (" .. tostring(n) .. " lines).") or ("Snapshot failed: " .. tostring(n)))
            UI.refresh()
        end)
    end, "ui snapshot")
    on(St.uiConns, prop(UI.liveBtn, "MouseButton1Click"), function()
        if St.live then
            API.stopLive()
            UI.setInfo("Live log stopped. Save to export.")
        else
            API.startLive()
            UI.setInfo("Live log running. Play the round, then Save.")
        end
        UI.refresh()
    end, "ui live")
    on(St.uiConns, prop(saveBtn, "MouseButton1Click"), function()
        UI.setInfo("Saving...")
        task.spawn(function()
            local ok, msg = API.save()
            UI.setInfo((ok and "Saved: " or "Save failed: ") .. tostring(msg))
            UI.refresh()
        end)
    end, "ui save")
    on(St.uiConns, prop(closeBtn, "MouseButton1Click"), function()
        -- penanda monoton (ring buffer berhenti nambah di cap)
        local unsaved = (St.pushed + St.snapN) ~= St.savedMark
        local t = now()
        if unsaved and not (St.closeArm and t - St.closeArm < 4) then
            St.closeArm = t
            UI.setInfo("Unsaved data. Click Close again to discard it.")
            return
        end
        API.unload()
    end, "ui close")

    -- Drag lewat title bar
    local dragging, dragStart, startPos = false, nil, nil
    on(St.uiConns, prop(title, "InputBegan"), function(input)
        local t = input.UserInputType
        if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = main.Position
        end
    end, "ui drag begin")
    on(St.uiConns, prop(UserInputService, "InputChanged"), function(input)
        local t = input.UserInputType
        if dragging and (t == Enum.UserInputType.MouseMovement or t == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end, "ui drag move")
    on(St.uiConns, prop(UserInputService, "InputEnded"), function(input)
        local t = input.UserInputType
        if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
            dragging = false
        end
    end, "ui drag end")
    UI.refresh()
end

-- Timer tunggal: diff GUI 2 dtk, cek tag baru 10 dtk, flush suppressed 1 dtk, status 0.5 dtk.
on(St.uiConns, prop(RunService, "Heartbeat"), function()
    if not St.alive then
        return
    end
    local t = now()
    if St.live then
        -- baris penutup LIGHT begitu window coalescing lewat (nilai akhir tween tidak hilang)
        if next(St.lightPend) ~= nil then
            local okL, errL = pcall(L.lightFlush, false)
            if not okL then
                noteErr("light flush", errL)
            end
        end
        if t - St.tGui >= 2 then
            St.tGui = t
            local okG, errG = pcall(L.guiScan)
            if not okG then
                noteErr("gui scan", errG)
            end
            local okR, errR = pcall(L.remoteTick)
            if not okR then
                noteErr("remote wait", errR)
            end
        end
        if t - St.tTags >= 10 then
            St.tTags = t
            local okT, errT = pcall(L.tags, true)
            if not okT then
                noteErr("tag rescan", errT)
            end
        end
        if t - St.tFlush >= 1 then
            St.tFlush = t
            flushRate(false)
        end
    end
    if t - St.tStatus >= 0.5 then
        St.tStatus = t
        UI.refresh()
    end
end, "heartbeat")

do
    local okUI, errUI = pcall(UI.build)
    if not okUI then
        noteErr("ui", errUI)
        warn("[NoctisENIX Inspector] UI failed: " .. tostring(errUI) .. " (API still works: getgenv().NoctisENIX_Inspector)")
    end
end

genv.NoctisENIX_Inspector = API
return API
